/* ---------------------------- lista de espera --------------------------- */
/* Uma senha de papel por pessoa, penduradas no fio da fila. A ordem que
   aparece é a ordem de chegada — o servidor já entrega assim. */
function renderEspera(){
  const total = filaEspera.length;
  const fila = $('filaEspera');

  /* A seção só existe quando há fila, ou quando a casa lotou e ela pode começar. */
  $('secaoEspera').hidden = !total && !capacidade.esgotado;
  $('contadorEspera').textContent = total;
  $('vazioEspera').hidden = total > 0;
  fila.hidden = !total;
  fila.innerHTML = '';
  if(!total) return;

  filaEspera.forEach((e,i)=>{
    const el = document.createElement('div');
    el.className = 'senha' + (i === 0 ? ' proximo' : '') +
                   (naEspera && naEspera.posicao === e.posicao ? ' voce' : '');
    el.style.animationDelay = (Math.min(i,14)*55) + 'ms';

    const num = document.createElement('div');
    num.className = 'num'; num.textContent = e.posicao + 'º';
    const picote = document.createElement('div');
    picote.className = 'picote';
    const quem = document.createElement('div');
    quem.className = 'quem'; quem.textContent = e.nome;
    el.appendChild(num); el.appendChild(picote); el.appendChild(quem);

    if(i === 0){
      const etiqueta = document.createElement('div');
      etiqueta.className = 'etiqueta'; etiqueta.textContent = 'próximo';
      el.appendChild(etiqueta);
    }
    fila.appendChild(el);
  });
}

